insert into public.posts (id, author_id, topic, kind, title, body, images, tips, points, menus, tags, keywords, location, taste_tags, pros, cons, created_at) values (md5('p-bbq')::uuid, md5('leehappy')::uuid, '푸드', 'normal', '음식점#릴라 바비큐 아산지중해', '바베큐 찐 맛집 발견! 단점으로는 맛있는데 먹다보니 물려서 아쉬웠음...기본 소스에 곁들여 ''4가지 버전''의 맛을 만들어내는 비법 공유!', '[{"src":"https://images.unsplash.com/photo-1461530927168-44328109da52?auto=format&fit=crop&w=720&q=70","alt":"그릴 위 바비큐 꼬치"},{"src":"https://images.unsplash.com/photo-1626323109697-df55d20f06a8?auto=format&fit=crop&w=720&q=70","alt":"구운 고기 플래터"}]'::jsonb, '[{"text":"주차는 지중해마을 ","strong":"공영주차장 이용이 가장 편함"},{"text":"해질녘 야외 테라스 자리는 빨리 매진되니 예약 필수!"},{"text":"","strong":"추천 메뉴","after":": 로즈마리 양갈비, 바질 치킨 스테이크, 삼겹 꼬치 플래터"},{"text":"와인 페어링 메뉴가 잘 준비돼 있어 커플 또는 단체 모임에 굿"},{"text":"","strong":"주말 저녁 라이브 음악 공연","after":". 좋은 자리 선착순"}]'::jsonb, null, '[{"name":"올 미트 꼬치 플래터","comment":"생각보다 양이 많아요 2인용인데 3명이서 먹어도 될듯","best":true},{"name":"시저 샐러드","comment":"야채가 싱싱하지 않음"}]'::jsonb, array['맛집','데이트','분위기']::text[], array['바비큐','맛집','아산','양갈비']::text[], '탕정면', '{"고기":0.9,"매운맛":0.3}'::jsonb, array['양이 넉넉함','야외 테라스 분위기','와인 페어링']::text[], array['먹다 보면 물림','샐러드 신선도 아쉬움']::text[], now() - interval '60 minutes') on conflict (id) do nothing;
